const text = $input.first().json.output.trim() || "";

let jsonString;

// STRATEGY: Find the actual JSON boundaries regardless of Markdown fluff
// Find the first '[' or '{'
const firstArray = text.indexOf('[');
const firstObj = text.indexOf('{');

// Determine if we are looking for an Array or an Object based on which comes first
let startIndex = -1;
let endIndex = -1;

if (firstArray !== -1 && (firstObj === -1 || firstArray < firstObj)) {
  // It's likely an array
  startIndex = firstArray;
  endIndex = text.lastIndexOf(']');
} else if (firstObj !== -1) {
  // It's likely an object
  startIndex = firstObj;
  endIndex = text.lastIndexOf('}');
}

if (startIndex !== -1 && endIndex !== -1 && endIndex > startIndex) {
  // Extract just the JSON part, ignoring text before or after (like ```json or ```)
  jsonString = text.substring(startIndex, endIndex + 1);
} else {
  // Fallback: Use the original text if no brackets were found (likely will fail parsing, but worth a try)
  jsonString = text;
}

// Now, parse the string we found
let parsed;
try {
  parsed = JSON.parse(jsonString);
} catch (err) {
  throw new Error("Failed to parse JSON: " + err.message + "\n\nAttempted to parse: \n" + jsonString);
}

// Check if the parsed result is an array
if (Array.isArray(parsed)) {
  // It's an array. Split them into separate n8n items.
  return parsed.map(item => ({ json: item }));
} else {
  // It's a single object. Return it as one n8n item.
  return [ { json: parsed } ];
}

