/**
https://www.youtube.com/
 * Scrape YouTube videos by auto-scrolling and extracting up to `maxVideos`.
 * Works in Chrome, Firefox, Safari, etc. with a custom `copy()` fallback.
 */
async function autoScrollAndScrape(maxVideos = Infinity) {
  /* ---------- fallback for copy() in non-Chrome browsers ---------- */
  function copy(data) {
    const textarea = document.createElement('textarea');
    textarea.value = typeof data === 'string' ? data : JSON.stringify(data, null, 2);
    textarea.style.position = 'fixed';
    document.body.appendChild(textarea);
    textarea.select();
    try {
      document.execCommand('copy');
      console.log('📋 Copied to clipboard!');
    } catch (err) {
      console.warn('❌ Copy to clipboard failed:', err);
    }
    document.body.removeChild(textarea);
  }

  /* ---------- helpers ---------- */
  const pause = (ms = 500) => new Promise(r => setTimeout(r, ms));
  const countVideosInDOM = () =>
    document.querySelectorAll('ytd-rich-grid-media, yt-lockup-view-model').length;

  async function scrollStep() {
    const distance = 600;
    window.scrollBy(0, distance);
    await pause(400);
  }

  /* ---------- 1. scroll until limit or content ends ---------- */
  let lastHeight = 0, sameHeight = 0;
  while (countVideosInDOM() < maxVideos && sameHeight < 5) {
    await scrollStep();
    const newHeight = document.documentElement.scrollHeight;
    if (newHeight === lastHeight) {
      sameHeight++;
    } else {
      sameHeight = 0;
      lastHeight = newHeight;
    }
  }

  /* ---------- 2. scrape video data ---------- */
  const videos = [];

  // a) Homepage-style grid
  document.querySelectorAll('ytd-rich-grid-media').forEach(item => {
    const linkEl     = item.querySelector('a#thumbnail');
    const titleEl    = item.querySelector('h3 a');
    const channelEl  = item.querySelector('ytd-channel-name a');
    const metas      = item.querySelectorAll('#metadata-line span');
    const durationEl = item.querySelector('ytd-thumbnail-overlay-time-status-renderer span');

    if (!linkEl) return;

    videos.push({
      url      : 'https://www.youtube.com' + linkEl.getAttribute('href'),
      title    : titleEl?.textContent.trim() ?? null,
      channel  : channelEl?.textContent.trim() ?? null,
      views    : metas[0]?.textContent.trim() ?? null,
      uploaded : metas[1]?.textContent.trim() ?? null,
      duration : durationEl?.textContent.trim() ?? null,
    });
  });

  // b) Lockup-style views (e.g., sidebars or search views)
  document.querySelectorAll('yt-lockup-view-model').forEach(item => {
    const linkEl     = item.querySelector('a[href*="/watch"]');
    const titleEl    = item.querySelector('.yt-lockup-metadata-view-model-wiz__title span');
    const channelEl  = item.querySelector('.yt-lockup-metadata-view-model-wiz__metadata span');
    const metas      = item.querySelectorAll('.yt-content-metadata-view-model-wiz__metadata-row span');
    const durationEl = item.querySelector('yt-thumbnail-badge-view-model .badge-shape-wiz__text');

    if (!linkEl) return;

    videos.push({
      url      : 'https://www.youtube.com' + linkEl.getAttribute('href'),
      title    : titleEl?.textContent.trim() ?? null,
      channel  : channelEl?.textContent.trim() ?? null,
      views    : metas[0]?.textContent.trim() ?? null,
      uploaded : metas[1]?.textContent.trim() ?? null,
      duration : durationEl?.textContent.trim() ?? null,
    });
  });

  /* ---------- 3. slice to maxVideos and output ---------- */
  const trimmed = videos.slice(0, maxVideos);
  console.log(`✅ Collected ${trimmed.length} videos (limit = ${maxVideos})`);
  console.log(trimmed);
  copy(trimmed);
  return trimmed;
}

/* ✅ Example usage: */
await autoScrollAndScrape(50);  // Get up to 50 videos

