    const durationEl = item.querySelector('yt-thumbnail-badge-view-model .badge-shape-wiz__text');

    const url = linkEl ? 'https://www.youtube.com' + linkEl.getAttribute('href') : null;
    const title = titleEl ? titleEl.textContent.trim() : null;
    const channel = channelEl ? channelEl.textContent.trim() : null;

    let views = null;
    let uploaded = null;

    if (metadataSpans.length >= 2) {
      views = metadataSpans[0].textContent.trim();
      uploaded = metadataSpans[1].textContent.trim();
    }

    const duration = durationEl ? durationEl.textContent.trim() : null;

    if (url) {
      videos.push({
        url,
        title,
        channel,
        views,
        uploaded,
        duration
      });
    }
  });

  console.log(JSON.stringify(videos, null, 2));
  return videos;
}

