async function autoScrollAndScrape(maxVideos = Infinity) {
  function copy(data) {
    const textarea = document.createElement('textarea');
    textarea.value = typeof data === 'string' ? data : JSON.stringify(data, null, 2);
    textarea.style.position = 'fixed';
    document.body.appendChild(textarea);
    textarea.select();
    try {
      document.execCommand('copy');
      console.log('📋 Copied to clipboard!');
    } catch (err) {
      console.warn('❌ Copy to clipboard failed:', err);
    }
    document.body.removeChild(textarea);
  }

  const pause = (ms = 500) => new Promise(r => setTimeout(r, ms));
  const countVideosInDOM = () => document.querySelectorAll('yt-lockup-view-model, ytd-rich-item-renderer, ytd-video-renderer').length;

  async function scrollStep() {
    window.scrollBy(0, 800);
    await pause(500);
  }

  let lastHeight = 0, sameHeight = 0;
  while (countVideosInDOM() < maxVideos && sameHeight < 5) {
    await scrollStep();
    const newHeight = document.documentElement.scrollHeight;
    if (newHeight === lastHeight) {
      sameHeight++;
    } else {
      sameHeight = 0;
      lastHeight = newHeight;
    }
  }

  const videos = [];

  // Scrape using a broader selector to catch different card types
  const cards = document.querySelectorAll('yt-lockup-view-model, ytd-rich-grid-media, ytd-video-renderer, ytd-grid-video-renderer');

  cards.forEach(item => {
    // 1. Get Link and ID
    const linkEl = item.querySelector('a#video-title-link, a[href*="/watch"]');
    if (!linkEl) return;

    const url = 'https://www.youtube.com' + linkEl.getAttribute('href');
    const idMatch = url.match(/v=([^&]+)/);
    const videoId = idMatch ? idMatch[1] : null;

    // 2. Get Title (Try multiple common selectors)
    const titleEl = item.querySelector('#video-title, .yt-lockup-metadata-view-model__title');
    const title = titleEl ? titleEl.textContent.trim() : null;

    // 3. Get Duration (Updated selector for 'yt-' prefix and 'wiz' fallback)
    const durationEl = item.querySelector('.yt-badge-shape__text, .badge-shape-wiz__text, span.ytd-thumbnail-overlay-time-status-renderer');
    const duration = durationEl ? durationEl.textContent.trim() : null;

    // 4. Smart Metadata Extraction
    // We get all text lines from the metadata block and sort them logicially
    let channel = null;
    let views = null;
    let uploaded = null;

    // Try to find the channel specific link first
    const channelEl = item.querySelector('.ytd-channel-name a, .yt-lockup-metadata-view-model__metadata a');
    if (channelEl) {
        channel = channelEl.textContent.trim();
    }

    // Grab all metadata spans to find views and date
    const metaSpans = item.querySelectorAll('.inline-metadata-item, .yt-content-metadata-view-model__metadata-row span');

    metaSpans.forEach(span => {
        const text = span.textContent.trim();
        if (!text) return;

        // Logic: specific keywords identify the data type
        if (text.includes('views') || text.includes('watching')) {
            views = text;
        } else if (text.match(/\d+ (second|minute|hour|day|week|month|year)s? ago/) || text.includes('Streamed')) {
            uploaded = text;
        } else if (!channel && text.length > 2 && !text.includes(':')) {
            // Fallback: if we didn't find a channel link, and this text isn't a timestamp, assume it's the channel name
            channel = text;
        }
    });

    videos.push({
      id: videoId,
      url,
      title,
      channel,
      views,
      uploaded,
      duration,
    });
  });

  // Remove duplicates based on ID
  const uniqueVideos = Array.from(new Map(videos.map(item => [item['id'], item])).values());
  const trimmed = uniqueVideos.slice(0, maxVideos);

  console.log(`✅ Collected ${trimmed.length} unique videos`);
  console.log(trimmed);
  copy(trimmed);
  return trimmed;
}

/* Run it */
